// Differential checks of ShareConstValues-faithful.js against Lean, generated by leanscript --check
import * as M from "./ShareConstValues-faithful.js";

function show(v) {
  if (Array.isArray(v) || ArrayBuffer.isView(v)) return "#[" + [...v].map(show).join(", ") + "]";
  // a list of cons cells (`ListRepr.taggedUnion`) is shown as its elements
  if (v !== null && typeof v === "object" && (v.tag === 0 || v.tag === 1)) {
    const a = [];
    for (; v.tag === 1; v = v._2) a.push(v._1);
    return show(a);
  }
  // a record (a structure-like type) is shown as its fields: `{a, b}`
  if (v !== null && typeof v === "object" && !("tag" in v) && "_1" in v) {
    const fs = [];
    for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
    return "{" + fs.join(", ") + "}";
  }
  return String(v);
}
// a union `{ tag: i, _1: …, … }` of leaf fields is shown as `i(…, …)`
function showUnion(v) {
  const fs = [];
  for (let i = 1; ("_" + i) in v; i++) fs.push(show(v["_" + i]));
  return v.tag + "(" + fs.join(", ") + ")";
}
function floatBits(x) {
  return String(new BigUint64Array(new Float64Array([x]).buffer)[0]);
}
function isNaNBits(s) {
  const b = BigInt(s);
  return ((b >> 52n) & 0x7ffn) === 0x7ffn && (b & 0xfffffffffffffn) !== 0n;
}
let passed = 0, failed = 0;
function check(label, thunk, expected, isFloat) {
  let got;
  try {
    const v = thunk();
    got = isFloat ? floatBits(v) : show(v);
    // NaN payloads differ between platforms: any NaN matches any NaN
    if (isFloat && Number.isNaN(v) && isNaNBits(expected)) got = expected;
  } catch (e) {
    got = "threw: " + e.message;
  }
  if (got === expected) passed++;
  else {
    failed++;
    console.log(`FAIL ${label}: expected ${JSON.stringify(expected)}, got ${JSON.stringify(got)}`);
  }
}

check("table", () => M.table, "#[1, 2, 3]", false);
check("same", () => M.same, "#[1, 2, 3]", false);
check("nested", () => M.nested, "#[#[1, 2, 3], #[4]]", false);
check("nested2", () => M.nested2, "#[#[1, 2, 3], #[4]]", false);
check("empty1", () => M.empty1, "#[]", false);
check("empty2", () => M.empty2, "#[]", false);
check("fresh(0n)", () => M.fresh(0n), "#[1, 2, 3, 0]", false);
check("fresh(1n)", () => M.fresh(1n), "#[1, 2, 3, 1]", false);
check("fresh(2n)", () => M.fresh(2n), "#[1, 2, 3, 2]", false);
check("fresh(5n)", () => M.fresh(5n), "#[1, 2, 3, 5]", false);
check("fresh(13n)", () => M.fresh(13n), "#[1, 2, 3, 13]", false);
check("freshConst(0n)", () => M.freshConst(0n), "#[1, 2, 3]", false);
check("freshConst(1n)", () => M.freshConst(1n), "#[1, 2, 3]", false);
check("freshConst(2n)", () => M.freshConst(2n), "#[1, 2, 3]", false);
check("freshConst(5n)", () => M.freshConst(5n), "#[1, 2, 3]", false);
check("freshConst(13n)", () => M.freshConst(13n), "#[1, 2, 3]", false);
check("later", () => M.later, "#[#[4], #[1, 2, 3]]", false);

console.log(`ShareConstValues-faithful.js: ${passed} passed, ${failed} failed`);
if (failed > 0) process.exit(1);
